using System.Net.Http.Json;
using sv_7c4773e5decb49e39a56e9993c24eb9f.Client.Models;

namespace sv_7c4773e5decb49e39a56e9993c24eb9f.Client.Services.WebAssembly;

public sealed class ClientShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ClientShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_7c4773e5decb49e39a56e9993c24eb9f.Client.Services;

namespace sv_7c4773e5decb49e39a56e9993c24eb9f.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        app.MapGet("api/shipments/{trackingNumber}", async (
            string trackingNumber,
            IShipmentService shipmentService,
            CancellationToken ct) =>
        {
            var shipment = await shipmentService.GetShipmentAsync(trackingNumber, ct);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });
    }
}

